package run.ikaros.password; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/password/items/{itemId}/secret-reference") public class SecretReferenceController{private final SecretReferenceService service;public SecretReferenceController(SecretReferenceService s){service=s;}@GetMapping public Mono<SecretReferenceView> get(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID itemId){return service.reference(a,itemId);}}
